#!/usr/bin/env bash
# {{NAME}} — generated by TERMy ({{LANG}})
set -euo pipefail

is_prime() {
    local n="$1" i
    if (( n < 2 )); then
        printf '%s is NOT prime (less than 2)\n' "$n"; return 0
    fi
    for ((i = 2; i * i <= n; i++)); do
        if (( n % i == 0 )); then
            printf '%s is NOT prime (divisible by %s)\n' "$n" "$i"; return 0
        fi
    done
    printf '%s is PRIME\n' "$n"
}

is_prime {{N}}